style.css:
/* UNIVERSAL CLEVER PINK & WHITE THEME */

/* Any div that contains the word Clever in its class or id */
div[class*="clever"], div[id*="clever"] {
    background-color: #ffb6c1 !important; /* soft pink background */
    color: #ffffff !important; /* white text */
    border-color: #ff69b4 !important; /* darker pink border */
    border-radius: 5px !important;
}

/* All buttons inside Clever bar */
div[class*="clever"] button {
    background-color: #ffffff !important; /* white buttons */
    color: #ff1493 !important; /* dark pink text */
    border: 1px solid #ff69b4 !important;
    border-radius: 5px !important;
}

/* All inputs inside Clever bar */
div[class*="clever"] input {
    background-color: #ffffff !important; /* white inputs */
    color: #ff1493 !important; /* dark pink text */
    border: 1px solid #ff69b4 !important;
    border-radius: 5px !important;
}

/* Links */
div[class*="clever"] a {
    color: #ff1493 !important;
    text-decoration: none;
}

div[class*="clever"] a:hover {
    text-decoration: underline;
}
